class BigPipeSubscriber:
    """
    BigPipe 队列消息订阅器
    """

    def __init__(self, config: Dict):
        """
        初始化订阅器

        Args:
            config: 配置字典，包含：
                - webservice: BigPipe服务地址，如 "host:port"
                - queue_name: 队列名称  
                - token: Queue token
                - encoding: 可选，编码格式，如 "base64"
        """
        self.webservice = config["webservice"]
        self.queue_name = config["queue_name"]
        self.token = config["token"]
        self.encoding = config.get("encoding")

        # 构造订阅URL
        self.subscribe_url = f"http://{self.webservice}/rest/queue/{self.queue_name}"

        # 构造确认URL
        self.ack_url = f"http://{self.webservice}/rest/queue/{self.queue_name}"

        logger.info(f"初始化 BigPipe 订阅器: {self.subscribe_url}")

    def receive_messages(self, timeout: int = 30) -> Optional[List[Dict]]:
        """
        从队列接收消息

        Args:
            timeout: 请求超时时间（秒）

        Returns:
            消息列表，每个消息包含 data 和 msgid，如果出错返回 None
        """
        params = {
            "method": "receive",
            "token": self.token
        }

        if self.encoding:
            params["encoding"] = self.encoding

        try:
            response = requests.post(
                self.subscribe_url,
                data=params,
                timeout=timeout
            )

            if response.status_code == 200:
                resp_data = response.json()
                if resp_data.get("status") == 0:
                    messages = resp_data.get("messages", [])
                    if messages:
                        logger.info(f"成功接收到 {len(messages)} 条消息")
                    return messages
                else:
                    logger.error(f"API返回错误状态: {resp_data}")
                    return None
            else:
                logger.error(f"HTTP错误: {response.status_code}, 响应: {response.text}")
                return None

        except requests.exceptions.RequestException as e:
            logger.error(f"请求异常: {e}")
            return None
        except json.JSONDecodeError as e:
            logger.error(f"JSON解析错误: {e}")
            return None

    def ack_message(self, msgid: str) -> bool:
        """
        确认消息已被处理

        Args:
            msgid: 消息ID

        Returns:
            是否确认成功
        """
        params = {
            "method": "ack",
            "token": self.token,
            "msgid": msgid
        }

        try:
            response = requests.post(self.ack_url, data=params, timeout=10)

            if response.status_code == 200:
                resp_data = response.json()
                if resp_data.get("status") == 0:
                    logger.info(f"消息确认成功: {msgid}")
                    return True
                else:
                    logger.error(f"确认失败: {resp_data}")
                    return False
            else:
                logger.error(f"确认HTTP错误: {response.status_code}, {response.text}")
                return False

        except requests.exceptions.RequestException as e:
            logger.error(f"确认请求异常: {e}")
            return False

    def process_message(self, message: Dict, callback=None) -> bool:
        """
        处理单条消息

        Args:
            message: 消息数据
            callback: 可选的处理回调函数

        Returns:
            是否处理成功
        """
        msgid = message.get("msgid")
        data = message.get("data", "")

        logger.info(f"处理消息 ID: {msgid}")
        logger.info(f"消息内容: {data}")

        try:
            if callback:
                # 使用用户提供的回调函数处理消息
                success = callback(data)
            else:
                # 默认处理逻辑：直接打印消息
                print(f"接收到消息: {data}")
                success = True

            if success:
                # 处理成功，确认消息
                return self.ack_message(msgid)
            else:
                logger.warning(f"消息处理失败，不进行确认: {msgid}")
                return False

        except Exception as e:
            logger.error(f"消息处理异常: {e}")
            return False

    def start_consuming(self, callback=None, interval: int = 5, max_messages: int = None):
        """
        开始持续消费消息

        Args:
            callback: 消息处理回调函数，接收消息内容作为参数，返回bool表示处理是否成功
            interval: 轮询间隔（秒）
            max_messages: 最大处理消息数，None表示无限制
        """
        logger.info(f"开始消费消息，间隔: {interval}秒")

        message_count = 0
        running = True

        def signal_handler(sig, frame):
            nonlocal running
            logger.info("接收到停止信号，正在停止...")
            running = False

        # 注册信号处理器
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

        try:
            while running:
                if max_messages and message_count >= max_messages:
                    logger.info(f"达到最大消息数限制: {max_messages}")
                    break

                messages = self.receive_messages()

                if messages:
                    for message in messages:
                        if not running:  # 检查是否应该停止
                            break

                        success = self.process_message(message, callback)
                        if success:
                            message_count += 1
                            logger.info(f"已处理消息数: {message_count}")

                # 如果没有消息或达到限制，等待下一次轮询
                if running and (not messages or (max_messages and message_count < max_messages)):
                    time.sleep(interval)

        except KeyboardInterrupt:
            logger.info("用户中断消费")
        except Exception as e:
            logger.error(f"消费过程发生异常: {e}")
        finally:
            logger.info(f"消息消费结束，共处理 {message_count} 条消息")```
