func initDataHub() error {
	// 加载配置
	confPath := "conf"
	var err error
	datahubConf := map[string]*local.DataHubConf{}
	if err = conf.Parse(confPath+"/datahub/datahub.toml", &datahubConf); err != nil {
		return fmt.Errorf("解析datahub配置失败: %v", err)
	}

	ddb.DatahubConfigs = datahubConf

	opts := []datahub.ClientOption{
		datahub.OptServicerMapper(servicer.DefaultMapper),
	}

	// 初始化客户端
	ddb.MEGAccessClient, err = datahub.NewClient("mq_access_meg", opts...)
	if err != nil {
		return fmt.Errorf("创建datahub客户端失败: %v", err)
	}

	ddb.MEGAccessPipeName = ddb.DatahubConfigs["mq_access_meg"].PipeConf.PipeName
	if ddb.MEGAccessPipeName == "" {
		return fmt.Errorf("mq_access_meg pipe name为空")
	}

	ddb.MEGAccessQueueConf = ddb.DatahubConfigs["mq_access_meg"].QueueConf

	log.Printf("初始化完成: PipeName=%s, QueueName=%s", ddb.MEGAccessPipeName, ddb.MEGAccessQueueConf.Name)
	return nil
}

func testSingleMessageConsume(ctx context.Context) error {
	queueName := ddb.MEGAccessQueueConf.Name
	token := ddb.MEGAccessQueueConf.Token
	windowSize := ddb.MEGAccessQueueConf.WindowSize

	log.Printf("测试消费消息: queue=%s, token=%s", queueName, token)

	ch := make(chan datahub.QueueResult)

	// 启动队列消费
	err := ddb.MEGAccessClient.Queue(ctx, queueName, token, windowSize, ch)
	if err != nil {
		return fmt.Errorf("启动队列失败: %v", err)
	}

	log.Println("等待消息...")

	select {
	case msg := <-ch:
		if msg.Err() != nil {
			return fmt.Errorf("接收消息错误: %v", msg.Err())
		}

		// 处理消息
		data := msg.Data()
		log.Printf("接收到消息: Len=%d bytes", len(data.Data))

		// 打印消息内容
		fmt.Println("=== 消息内容 ===")
		fmt.Printf("Data: %s\n", string(data.Data))
		fmt.Printf("MsgID: %v\n", data.MsgID)
		fmt.Printf("Timestamp: %v\n", data.Timestamp)
		fmt.Println("================")

		// 尝试解析JSON格式的消息
		var jsonData map[string]interface{}
		if err := json.Unmarshal(data.Data, &jsonData); err == nil {
			fmt.Println("=== JSON解析结果 ===")
			prettyJSON, _ := json.MarshalIndent(jsonData, "", "  ")
			fmt.Println(string(prettyJSON))
			fmt.Println("=====================")
		} else {
			log.Printf("消息不是JSON格式: %v", err)
		}

		// 确认消息
		if err := msg.Ack(ctx); err != nil {
			log.Printf("确认消息失败: %v", err)
			return err
		}
		log.Println("消息确认成功")

		return nil

	case <-time.After(30 * time.Second):
		log.Println("等待消息超时，30秒内未收到消息")
		return fmt.Errorf("接收消息超时")
	case <-ctx.Done():
		log.Println("上下文已取消")
		return ctx.Err()
	}
}

func main() {
	log.Println("开始测试直接消费消息...")

	// 初始化datahub
	if err := initDataHub(); err != nil {
		log.Fatalf("初始化失败: %v", err)
	}

	ctx := context.Background()

	// 测试消费一条消息
	if err := testSingleMessageConsume(ctx); err != nil {
		log.Printf("消费测试失败: %v", err)
	} else {
		log.Println("消费测试成功完成")
	}
}
