package tpdb

import (
	"encoding/json"
	"fmt"
	"time"

	"icode.baidu.com/baidu/poi/arch-service-poi-tp-access/library/resource"
)

// CustomTime 自定义时间类型，用于处理MySQL时间字段的扫描
type CustomTime struct {
	time.Time
}

// Scan 实现sql.Scanner接口
func (ct *CustomTime) Scan(value interface{}) error {
	if value == nil {
		ct.Time = time.Time{} // 空时间
		return nil
	}

	switch v := value.(type) {
	case []byte:
		// MySQL返回的字符串格式时间
		str := string(v)
		if str == "" || str == "0000-00-00 00:00:00" {
			ct.Time = time.Time{}
			return nil
		}
		return ct.parseDateTime(str)
	case string:
		// 字符串类型直接处理
		if v == "" || v == "0000-00-00 00:00:00" {
			ct.Time = time.Time{}
			return nil
		}
		return ct.parseDateTime(v)
	case time.Time:
		// 已经是time.Time类型
		ct.Time = v
		return nil
	default:
		return fmt.Errorf("unsupported Scan, storing driver.Value type %T into type *CustomTime", value)
	}
}

// parseDateTime 解析日期时间字符串
func (ct *CustomTime) parseDateTime(value string) error {
	// 尝试多种常见的时间格式
	formats := []string{
		"2006-01-02 15:04:05",
		"2006-01-02T15:04:05Z",
		time.RFC3339,
	}

	var err error
	for _, format := range formats {
		ct.Time, err = time.Parse(format, value)
		if err == nil {
			return nil
		}
	}

	return fmt.Errorf("无法解析时间格式: %s", value)
}

type AuditResult struct {
	ID           int64      `json:"id" gorm:"column:id;primaryKey;autoIncrement"`
	TraceID      string     `json:"trace_id" gorm:"column:trace_id;size:64;not null"`
	SendExtra    string     `json:"send_extra" gorm:"column:send_extra;type:json"`
	AuditStatus  int        `json:"audit_status" gorm:"column:audit_status;not null"`
	AuditStage   string     `json:"audit_stage" gorm:"column:audit_stage;size:32;not null"`
	Bid          int64      `json:"bid" gorm:"column:bid"`
	DetailReason string     `json:"detail_reason" gorm:"column:detail_reason;type:text"`
	StoreID      int64      `json:"store_id" gorm:"column:store_id;not null"`
	PoiName      string     `json:"poi_name" gorm:"column:poi_name;size:256"`
	Address      string     `json:"address" gorm:"column:address;size:512"`
	City         string     `json:"city" gorm:"column:city;size:64"`
	AuditTime    int        `json:"audit_time" gorm:"column:audit_time;not null"`
	Operator     string     `json:"operator" gorm:"column:operator;size:64"`
	CreatedTime  CustomTime `json:"created_time" gorm:"column:created_time;type:timestamp;default:CURRENT_TIMESTAMP"`
	UpdatedTime  CustomTime `json:"updated_time" gorm:"column:updated_time;type:timestamp;default:CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP"`
}

func (ar *AuditResult) TableName() string {
	return "tp_t_audit_result"
}

// Create 创建审核记录
func (ar *AuditResult) Create() error {
	return resource.OrmClientUser.Create(ar).Error
}

// GetByTraceID 根据trace_id查询单条记录
func (ar *AuditResult) GetByTraceID(traceID string) error {
	return resource.OrmClientUser.Where("trace_id = ?", traceID).First(ar).Error
}

// Update 更新审核记录
func (ar *AuditResult) Update() error {
	return resource.OrmClientUser.Save(ar).Error
}

// Delete 删除审核记录
func (ar *AuditResult) Delete() error {
	return resource.OrmClientUser.Delete(ar).Error
}

// BatchCreate 批量创建审核记录
func BatchCreate(auditResults []*AuditResult) error {
	return resource.OrmClientUser.CreateInBatches(auditResults, 100).Error
}

// ListByStoreID 根据store_id查询审核记录
func ListByStoreID(storeID int64, limit int) ([]AuditResult, error) {
	var results []AuditResult
	err := resource.OrmClientUser.
		Where("store_id = ?", storeID).
		Order("audit_time DESC").
		Limit(limit).
		Find(&results).Error
	return results, err
}

// CountByStatus 统计不同审核状态的数量
func CountByStatus(storeID int64) (map[int]int64, error) {
	var counts []struct {
		AuditStatus int
		Count       int64
	}

	result := make(map[int]int64)
	err := resource.OrmClientUser.Model(&AuditResult{}).
		Select("audit_status, COUNT(*) as count").
		Where("store_id = ?", storeID).
		Group("audit_status").
		Scan(&counts).Error

	if err != nil {
		return nil, err
	}

	for _, c := range counts {
		result[c.AuditStatus] = c.Count
	}
	return result, nil
}

// ConvertSendExtraToMap 将send_extra转换为map
func (ar *AuditResult) ConvertSendExtraToMap() (map[string]interface{}, error) {
	var extra map[string]interface{}
	err := json.Unmarshal([]byte(ar.SendExtra), &extra)
	return extra, err
}

