package access

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"strconv"
	"strings"
	"time"

	"icode.baidu.com/baidu/de-perceive-arch/common-lib/taskcome"
	"icode.baidu.com/baidu/poi/arch-service-poi-tp-access/dao/ddb"
	"icode.baidu.com/baidu/poi/arch-service-poi-tp-access/dao/tpdb"
	"icode.baidu.com/baidu/poi/arch-service-poi-tp-access/library/dag"
	"icode.baidu.com/baidu/poi/arch-service-poi-tp-access/library/datahub"
	"icode.baidu.com/baidu/poi/arch-service-poi-tp-access/library/global"
	"icode.baidu.com/baidu/poi/arch-service-poi-tp-access/library/resource"
	"icode.baidu.com/baidu/poi/arch-service-poi-tp-access/model/utils"
)

// GlobalStartDagFunc 全局变量，用于在测试中替换taskcome.StartDag函数
var GlobalStartDagFunc func(ctx context.Context, dagName string, paramsStr string, planID string, ak string, sk string) error = taskcome.StartDag

type MEGAccessConsumer struct {
	ctx context.Context
	*datahub.ConsumerPool
}

func NewMEGAccessConsumer(ctx context.Context, workerNum int, conf *datahub.QueueConf) *MEGAccessConsumer {
	// 创建 ConsumerPool
	pool := datahub.NewConsumerPool(ddb.MEGAccessClient, workerNum, conf, resource.Logger)
	if pool == nil {
		return nil
	}

	consumer := &MEGAccessConsumer{
		ConsumerPool: pool,
		ctx:          ctx,
	}
	consumer.SetProcessFunc(consumer.process)
	return consumer
}
func (c *MEGAccessConsumer) process(msg datahub.Message) error {
	var raw = msg.Data().Data
	resource.Logger.Notice(c.ctx, fmt.Sprintf("start process, data:%v", string(raw)))

	// 解析请求参数
	req, err := c.parseRequest(raw)
	if err != nil {
		resource.Logger.Notice(c.ctx, fmt.Sprintf("parse request failed: %v", err))
		return nil
	}

	// 启动审核 DAG
	err = c.StartAuditDag(c.ctx, req, raw)
	if err != nil {
		resource.Logger.Warning(c.ctx, fmt.Sprintf("start dag failed: %v", err))
		return err
	}
	return nil
}

// parseRequest 解析请求数据并返回 TaskComeRequest
func (c *MEGAccessConsumer) parseRequest(raw []byte) (*global.TaskComeRequest, error) {
	var req global.TaskComeRequest
	if err := req.UnmarshalJSON(raw); err != nil {
		log.Printf("解析请求失败: %v", err)
		return nil, err
	}
	return &req, nil
}

// prepareAuditParams 准备审核参数
func (c *MEGAccessConsumer) prepareAuditParams(req *global.TaskComeRequest) (*global.TaskComeRequest, error) {
	params := *req
	params.PlanID = strings.ReplaceAll(req.TraceID, "-", "_")
	params.Tid = req.StoreID
	params.CreateTime = time.Now().Unix()
	params.PanChongWay = "common"
	params.PanChongSrcType = "tp_meg"
	params.ReqID = 1204
	params.Tpl = "[{\"name\":\"b_id\",\"desc\":\"ID\"},{\"name\":\"b_name\",\"desc\":\"名称\"},{\"name\":\"b_addr\",\"desc\":\"地址\"},{\"name\":\"b_city\",\"desc\":\"城市\"},{\"name\":\"b_phone\",\"desc\":\"电话\"},{\"name\":\"b_time\",\"desc\":\"营业时间\"},{\"name\":\"b_status\",\"desc\":\"营业状态\"},{\"name\":\"b_show_tag\",\"desc\":\"TAG\"},{\"name\":\"b_content_tag\",\"desc\":\"展示标签\"},{\"name\":\"b_content_recall_tag\",\"desc\":\"召回标签\"},{\"name\":\"b_brand\",\"desc\":\"品牌\"},{\"name\":\"b_shop_photo\",\"desc\":\"头图\"},{\"name\":\"raw_point_x\",\"desc\":\"经度\"},{\"name\":\"raw_point_y\",\"desc\":\"纬度\"}]"
	params.CheckSrc = "zt_hotel.shenjielv_tp"
	params.DataType = global.DataTypeOnline
	params.CityVerify = false
	params.LaunchWay = json.RawMessage("{\"is_pass\":\"1\",\"gl_route\":\"stop\",\"ns_route\":\"juejin\",\"add_route\":\"juejin\",\"celue_src\":\"tp.shangye_celue\",\"rengong_src\":\"feibiao.tp_fankui\",\"tips\":\"\",\"name_block_word\":\"\",\"operator\":\"mengyuehua_cd\",\"man_panchong_proj\":\"TPP\",\"man_chuodian_proj\":\"TPC\",\"flow_switch\":\"STOP\",\"priority\":29,\"man_priority\":9,\"shop_hours_acces\":\"2\"}")

	return &params, nil
}

// createDAG 创建并启动审核 DAG
func (c *MEGAccessConsumer) createDAG(ctx context.Context, params *global.TaskComeRequest) error {
	params.NodeIDFrom = "" // 第一个请求是不知
	// 动态获取DAG的第一个节点
	config, exists := dag.GetDAGConfig(global.TaskComeNewAuditStartTPDagName)
	if !exists {
		return fmt.Errorf("failed to find DAG config: %s", global.TaskComeNewAuditStartTPDagName)
	}
	// 使用DAG的head节点作为第一个节点
	if config.Head.NodeID == 0 {
		return fmt.Errorf("DAG config has invalid head node: %s", global.TaskComeNewAuditStartTPDagName)
	}
	params.NodeIDTo = strconv.Itoa(config.Head.NodeID)

